    ):
        self.store = store
        self.recall_engine = MemoryRecall(store)
        self.consolidator = MemoryConsolidator(store)
        self.extractor =  MemoryExtractor(model)
        self.auto_extract = auto_extract


    def remember(
        self,
        content: str,
        category: str,
        tags: list[str] | None = None,
        source: str = "agent",
    ) -> str:

        item = (
            self.consolidator.save(
                content=content,
                category=category,
                tags=tags,
                source=source,
            )
        )

        return (
            f"Memory saved: "
            f"{item.id}"
        )

    def recall(
        self,
        query: str,
        limit: int = 5,
    ) -> str:

        return (
            self.recall_engine.render(
                query=query,
                limit=limit,
            )
        )

