VALID_TASK_STATUSES = {
    "pending",
    "in_progress",
    "completed",
    "failed",
}


class TaskScheduler:

    def __init__(
        self,
        store: TaskStore,
    ):
        self.store = store
        self.graph = TaskGraph(store)

    def create(
        self,
        title: str,
        description: str = "",
        depends_on: list[str] | None = None,
    ) -> str:

        dependencies = (
            depends_on or []
        )

        self.graph.validate_dependencies(
            dependencies
        )

        task = self.store.create(
            title=title,
            description=description,
            depends_on=dependencies,
        )

        try:
            self.graph.validate_no_cycles()

        except Exception:
            raise

        return (
            f"Created {task.id}: "
            f"{task.title}"
        )

    def update(
        self,
        task_id: str,
        status: str,
        result: str | None = None,
    ) -> str:

        if status not in (
            VALID_TASK_STATUSES
        ):
            return (
                f"Error: invalid status "
                f"'{status}'"
            )

        task = self.store.get(
            task_id
        )

        if task is None:
            return (
                f"Error: unknown task "
                f"'{task_id}'"
            )

        if (
            status == "in_progress"
            and self.graph.is_blocked(
                task
            )
        ):
            return (
                "Error: task is blocked "
                "by unfinished dependencies"
            )

        if (
            status == "completed"
            and self.graph.is_blocked(
                task
            )
        ):
            return (
                "Error: cannot complete "
                "a blocked task"
            )

        task.status = status

        if result is not None:
            task.result = result

        self.store.update(
            task
        )

        return (
            f"Updated {task.id} "
            f"to {status}"
        )

    def render(
        self,
    ) -> str:

        tasks = self.store.all()

        if not tasks:
            return "(no persistent tasks)"

        lines = []

        for task in tasks:

            status = (
                self.graph
                .display_status(
                    task
                )
            )

            dependency_text = ""

            if task.depends_on:

                dependency_text = (
                    " depends_on="
                    + ",".join(
                        task.depends_on
                    )
                )

            lines.append(
                f"- {task.id} "
                f"[{status}] "
                f"{task.title}"
                f"{dependency_text}"
            )

        runnable = (
            self.graph.runnable()
        )

        if runnable:

            lines.append(
                "\nRunnable now:"
            )

            for task in runnable:

                lines.append(
                    f"- {task.id}: "
                    f"{task.title}"
                )

        return "\n".join(lines)

