                )

            if not isinstance(
                description,
                str,
            ):
                return (
                    "Error: description "
                    "must be string"
                )

            if not isinstance(
                depends_on,
                list,
            ):
                return (
                    "Error: depends_on "
                    "must be list"
                )

            clean_dependencies = [
                dependency
                for dependency in depends_on
                if isinstance(
                    dependency,
                    str,
                )
            ]

            try:
                return self.create(
                    title=title,
                    description=description,
                    depends_on=(
